async function faseClip(env, cfg, L) {
  const fonte = FONTI[L.fonte || "pcloud"] || FONTI.pcloud;
  if (!fonte.pronta(L)) {
    await log(env, L.id, "analista", "nessun girato collegato: preparo scheda e lista delle riprese");
    return true;
  }
  let clip = J(L.clip, null);
  if (!clip) {
    const lista = await fonte.elenca(L, env);
    if (!lista.filter((c) => c.tipo !== "musica").length) throw new Error(L.fonte === "archivio" ? `nella cartella ${L.pcloud} dell'archivio non ci sono n\xE9 video n\xE9 foto` : "nella cartella pCloud non ci sono n\xE9 video n\xE9 foto");
    if (env.ARCHIVIO && !lista.some((c) => c.tipo === "musica") && !/senza musica|musica.{0,30}(instagram|edits|la metto io)/i.test(L.prompt || "")) {
      const st = J(L.stile, null);
      const b = await branoArchivio(env, async (brani) => {
        const r = await claude(
          { ...cfg, CLAUDE_MODEL: cfg.CLAUDE_MODEL_LIGHT || cfg.CLAUDE_MODEL },
          'Scegli la musica per un reel. Rispondi solo JSON {"i": numero}.',
          `REEL: ${L.prompt}
STILE: ${st?.nome || st?.genere || "-"} ${(st?.mood || []).join(", ")}
BRANI (umore = sottocartella):
${JSON.stringify(brani)}
Scegli il brano pi\xF9 adatto all'umore del reel.`,
          { maxTokens: 60 }
        );
        return Number(r?.i);
      }).catch(() => null);
      if (b) {
        lista.push(b);
        await log(env, L.id, "regista", `\u{1F3B5} musica dall'archivio: ${b.cartella.split("/").slice(1).join(" / ") || "Musica"} \xB7 ${b.nome}`);
      }
    }
    clip = lista.map((c) => ({ ...c, stato: "da_guardare" }));
    let gia = 0;
    for (const c of clip) {
      const r = await one(env, "SELECT dati FROM cache_analisi WHERE chiave=?", chiaveClip(c));
      if (r) {
        const d = J(r.dati, {});
        Object.assign(c, { stato: "fatto", analisi: d.analisi || d, tecnico: d.tecnico || c.tecnico });
        gia++;
      }
    }
    await run(env, "UPDATE lavori SET clip=?, motore_visto=? WHERE id=?", JSON.stringify(clip), ora(), L.id);
    const peso = Math.round(clip.reduce((s, c) => s + (c.dimensione || 0), 0) / 1073741824 * 10) / 10;
    await log(env, L.id, "analista", `${clip.length} clip trovate (${fonte.nome}, ${peso} GB)${gia ? `, ${gia} gi\xE0 viste in passato` : ""}`);
    if (clip.some((c) => c.stato === "da_guardare")) await log(env, L.id, "motore", "chiamo il motore GitHub: scarico e misuro le clip per Ada");
  }
  if (!clip.some((c) => c.stato === "da_guardare")) {
    const brutte = clip.filter((c) => c.stato === "fatto" && (c.analisi?.problemi || []).length);
    if (brutte.length && !J(L.montaggio, null)?.consigli_dario) {
      const tipi = {};
      for (const c of brutte) for (const pr of [].concat(c.analisi.problemi)) {
        const k = String(pr.tipo || pr).toLowerCase().split(/[ :,(]/)[0];
        tipi[k] = (tipi[k] || 0) + 1;
      }
      const top = Object.entries(tipi).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([k, n]) => `${k} (${n})`).join(", ");
      await log(env, L.id, "videomaker", `\u{1F4F1} Dario: ${brutte.length} clip su ${clip.length} hanno problemi (${top}). Rocco user\xE0 i tratti buoni; alla prossima ripresa: camera ferma o gimbal, pi\xF9 luce, 2-3 secondi di margine prima e dopo ogni azione.`);
    }
    return true;
  }
  return avvisoMotore(env, L);
}
