    const chiave = `post-${P2.id}/${d.n}-${k + 1}.png`;
    if (file[chiave]) continue;
    if (fatti >= 12) {
      mancano++;
      continue;
    }
    const r = await fetch(u);
    if (!r.ok) throw new Error(`slide ${d.n}.${k + 1} non scaricabile da Canva (${r.status}): rifai l'esportazione`);
