  const passi = '<div class="riga" style="flex-wrap:wrap;gap:6px;margin:10px 0">' + FASI_AV.map((f, k) => '<span class="pill ' + (k < i || A.fase === 'fatto' ? 'pronto' : k === i ? 'corso' : '') + '">' + f[1] + '</span>').join('') + '</div>';
  const R = A.ricerca, V = A.virali;
