  const visibili = acceso ? Math.min(titolo.length, Math.floor(((t - (P.t0 || 0)) * 22) % (titolo.length + 40))) : titolo.length;
  const nr = righeTesto(g, titolo.slice(0, visibili) + (acceso && Math.floor(t * 2) % 2 ? '\u258D' : ''), 16, 74, larg, 26, 3);
  g.font = '15px ui-monospace, Menlo, monospace'; g.fillStyle = '#8fa2c8';
